var drawV8SimulatorCanvas = window.drawV8SimulatorCanvas = function(canvas, sim, p1, p2, p3) {
  if (!canvas) return { metric1: '—', metric2: '—', metric3: '—', statusText: 'Ready' };
  const ctx = canvas.getContext('2d');
  if (!ctx) return { metric1: '—', metric2: '—', metric3: '—', statusText: 'Ready' };
  const W = canvas.width = 680;
  const H = canvas.height = 320;
  ctx.clearRect(0, 0, W, H);
  if (typeof ctx.createRadialGradient === 'function') {
    const bgGrad = ctx.createRadialGradient(W * 0.5, H * 0.42, 18, W * 0.5, H * 0.5, W * 0.65);
    bgGrad.addColorStop(0, '#0d1f3a');
    bgGrad.addColorStop(0.55, '#071224');
    bgGrad.addColorStop(1, '#040914');
    ctx.fillStyle = bgGrad;
  } else {
    ctx.fillStyle = '#07101e';
  }
  ctx.fillRect(0, 0, W, H);

  // Subtle celestial oscilloscope coordinate grid & phase horizon
  ctx.strokeStyle = 'rgba(89,194,255,0.075)';
  ctx.lineWidth = 1;
  for (let gx = 40; gx < W; gx += 60) { ctx.beginPath(); ctx.moveTo(gx, 0); ctx.lineTo(gx, H); ctx.stroke(); }
  for (let gy = 40; gy < H; gy += 50) { ctx.beginPath(); ctx.moveTo(0, gy); ctx.lineTo(W, gy); ctx.stroke(); }
  ctx.strokeStyle = 'rgba(230,200,138,0.16)';
  ctx.beginPath(); ctx.moveTo(24, H * 0.5); ctx.lineTo(W - 24, H * 0.5); ctx.stroke();
  ctx.shadowBlur = 9;
  ctx.shadowColor = 'rgba(89,194,255,0.32)';

  const id = sim.id;
  if (id === 'dyadic') {
    const J = Math.round(p1);
    const delta = p2;
    const chirp = p3;
    let rawPeak = 0;
    let cancelledEnergy = 0;
    // Draw individual dyadic shells in cyan/purple and damped sum in gold
    for (let j = 1; j <= J; j++) {
      const amp = Math.pow(2, -delta * j);
      cancelledEnergy += amp * amp;
      rawPeak += amp;
      ctx.strokeStyle = `hsla(${190 + j * 16}, 80%, 62%, 0.35)`;
      ctx.lineWidth = 1.2;
      ctx.beginPath();
      for (let x = 20; x < W - 20; x += 3) {
        const t = (x - 20) / (W - 40) * Math.PI * 4;
        const y = H * 0.5 - Math.cos(Math.pow(2, Math.min(j, 5)) * t + chirp * 0.3 * j) * amp * 110;
        if (x === 20) ctx.moveTo(x, y); else ctx.lineTo(x, y);
      }
      ctx.stroke();
    }
    ctx.strokeStyle = '#e5c687';
    ctx.lineWidth = 2.6;
    ctx.beginPath();
    for (let x = 20; x < W - 20; x += 2) {
      const t = (x - 20) / (W - 40) * Math.PI * 4;
      let sum = 0;
      for (let j = 1; j <= J; j++) {
        sum += Math.pow(2, -delta * j) * Math.cos(Math.pow(2, Math.min(j, 5)) * t + chirp * 0.3 * j);
      }
      const y = H * 0.5 - sum * 85;
      if (x === 20) ctx.moveTo(x, y); else ctx.lineTo(x, y);
    }
    ctx.stroke();
    const l2Gain = ((1 - Math.sqrt(cancelledEnergy) / Math.max(0.01, rawPeak)) * 100).toFixed(1) + '%';
    return {
      metric1: `${rawPeak.toFixed(2)} (Triangle Sum)`,
      metric2: `${Math.sqrt(cancelledEnergy).toFixed(2)} (Orthogonal L²)`,
      metric3: `${l2Gain} Commutator Cancellation`,
      statusText: `Octaves 1..${J} summed with 2^{-${delta.toFixed(2)}j} decay`
    };
  }

  if (id === 'ricci') {
    const t = p1;
    const delta = p2;
    const neckR = Math.max(0.06, 0.65 * (1 - 0.92 * t));
    const surgeryTriggered = neckR <= delta;
    ctx.strokeStyle = surgeryTriggered ? '#34d399' : '#59c2ff';
    ctx.lineWidth = 2.8;
    // Top and bottom profile of dumbbell manifold
    for (const sign of [-1, 1]) {
      ctx.beginPath();
      for (let x = 60; x <= W - 60; x += 4) {
        const u = (x - W / 2) / ((W - 120) / 2); // -1 to 1
        if (surgeryTriggered && Math.abs(u) < 0.16) continue;
        const lobe = Math.sqrt(Math.max(0, 1 - u * u)) * (0.35 + 0.65 * u * u);
        const radius = (neckR * (1 - u * u) + lobe) * 115;
        const y = H / 2 + sign * radius;
        if (x === 60 || (surgeryTriggered && Math.abs(u - 0.16) < 0.02)) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
      }
      ctx.stroke();
    }
    const wEntropy = (4.2 - 1.8 * t - (surgeryTriggered ? 0.45 : 0)).toFixed(2);
    return {
      metric1: `r_neck = ${neckR.toFixed(3)}`,
      metric2: `W(g,f,τ) = -${wEntropy}`,
      metric3: surgeryTriggered ? 'Neckpinch Excised (Caps Glued)' : 'Smooth Ricci Flow Evolution',
      statusText: surgeryTriggered ? 'Surgery ratchet triggered: reduced volume dropped by ΔV > δ³' : 'Approaching neckpinch threshold'
    };
  }

  if (id === 'pinning') {
    const pins = Math.round(p1);
    const alpha = p2;
    const N = Math.round(p3);
    const cx = W * 0.5, cy = H * 0.5, R = 115;
    const nodes = [];
    for (let i = 0; i < N; i++) {
      const ang = (i * Math.PI * 2) / N - Math.PI / 2;
      nodes.push({ x: cx + Math.cos(ang) * R, y: cy + Math.sin(ang) * R, pinned: i < pins });
    }
    let activeEdges = 0;
    for (let i = 0; i < N; i++) {
      for (let j = i + 1; j < N; j++) {
        if ((i * 7 + j * 3) % 5 !== 0) continue;
        const severed = nodes[i].pinned || nodes[j].pinned;
        if (!severed) activeEdges++;
        ctx.strokeStyle = severed ? 'rgba(229,198,135,0.12)' : 'rgba(252,129,129,0.55)';
        ctx.lineWidth = severed ? 1 : 1.6;
        ctx.beginPath(); ctx.moveTo(nodes[i].x, nodes[i].y); ctx.lineTo(nodes[j].x, nodes[j].y); ctx.stroke();
      }
    }
    nodes.forEach((nd, i) => {
      ctx.fillStyle = nd.pinned ? '#e5c687' : '#59c2ff';
      ctx.beginPath(); ctx.arc(nd.x, nd.y, nd.pinned ? 7.5 : 5, 0, Math.PI * 2); ctx.fill();
    });
    const initEnt = (N * 0.68).toFixed(1);
    const remCorrelation = Math.max(0.02, (alpha / (pins + 1.5)) * 0.28).toFixed(3);
    return {
      metric1: `${initEnt} bits Initial Entropy`,
      metric2: `I(X_i ; X_j | Pins) = ${remCorrelation}`,
      metric3: `${activeEdges} Active Tangled Chords`,
      statusText: `${pins} heavy hubs pinned → residual system ${Number(remCorrelation) < 0.25 ? 'ε-independent!' : 'still coupled'}`
    };
  }

  if (id === 'sphere') {
    const r0 = p1;
    const m = p2;
    const dim = p3;
    const zeroY = H * 0.62;
    ctx.strokeStyle = 'rgba(255,255,255,0.25)';
    ctx.beginPath(); ctx.moveTo(30, zeroY); ctx.lineTo(W - 30, zeroY); ctx.stroke();
    // Draw radial magic filter f(r)
    ctx.strokeStyle = '#e5c687';
    ctx.lineWidth = 2.6;
    ctx.beginPath();
    for (let x = 40; x < W - 40; x += 3) {
      const r = 0.2 + ((x - 40) / (W - 80)) * 3.2;
      const val = (r0 - r) * Math.pow(Math.sin(Math.PI * (r / r0)), 2) * Math.exp(-0.45 * r * (m / 6));
      const y = zeroY - val * 180;
      if (x === 40) ctx.moveTo(x, y); else ctx.lineTo(x, y);
    }
    ctx.stroke();
    // Mark double zeros at lattice radii
    for (let k = 1; k <= 4; k++) {
      const rk = Math.sqrt(2 * k) * (r0 / 1.414);
      const xk = 40 + ((rk - 0.2) / 3.2) * (W - 80);
      if (xk > 40 && xk < W - 40) {
        ctx.fillStyle = k === 1 ? '#34d399' : '#59c2ff';
        ctx.beginPath(); ctx.arc(xk, zeroY, 5.5, 0, Math.PI * 2); ctx.fill();
      }
    }
    const density = dim === 8 ? 'π⁴ / 384 ≈ 0.25367' : (dim === 24 ? 'π¹² / 12! ≈ 0.00193' : `C_${dim} ≤ 2^{-0.599·${dim}}`);
    return {
      metric1: `r₀ = ${r0.toFixed(2)} (First Sign Flip)`,
      metric2: `Δ_${dim} = ${density}`,
      metric3: `Double Zeros Locked at √(2k)`,
      statusText: `f(r) ≤ 0 for r ≥ ${r0.toFixed(2)} and f̂(ξ) ≥ 0 for all ξ`
    };
  }

  // Generic rich visual renderer for Simulators 5..12 (KAM, RG, LLL, SoS, Carleman, BSD, Snell, Expander)
  const cx = W * 0.5, cy = H * 0.5;
  ctx.strokeStyle = '#59c2ff';
  ctx.lineWidth = 2.2;
  ctx.beginPath();
  for (let x = 35; x < W - 35; x += 3) {
    const u = (x - 35) / (W - 70);
    let y = cy;
    if (id === 'kam') {
      const theta = u * Math.PI * 2;
      const rad = 85 + 22 * p1 * Math.sin(5 * theta) / Math.max(0.25, Math.pow(p2, -0.6)) * Math.pow(0.5, p3 - 1);
      const px = cx + Math.cos(theta) * rad * 1.4;
      const py = cy + Math.sin(theta) * rad * 0.9;
      if (x === 35) ctx.moveTo(px, py); else ctx.lineTo(px, py);
    } else if (id === 'rg') {
      const decay = Math.pow(p3, -p2 * (u * p1));
      y = H * 0.8 - decay * 200 * Math.cos(u * 6);
      if (x === 35) ctx.moveTo(x, y); else ctx.lineTo(x, y);
    } else if (id === 'lll') {
      const lllCrit = Math.E * (p2 / 100) * (p1 + 1);
      const branch = Math.pow(Math.min(1.35, lllCrit), u * p3);
      y = H * 0.82 - branch * 120 - 18 * Math.sin(u * 18);
      if (x === 35) ctx.moveTo(x, y); else ctx.lineTo(x, y);
    } else if (id === 'sos') {
      const z = (u - 0.5) * 3.2;
      const poly = Math.pow(z * z - 1, 2) + p2 * z + 0.35;
      y = H * 0.82 - poly * 85;
      if (x === 35) ctx.moveTo(x, y); else ctx.lineTo(x, y);
    } else if (id === 'carleman') {
      const z = (u - 0.5) * 2.0;
      const bump = p2 * Math.exp(-18 * (z - 0.15) * (z - 0.15)) * Math.exp(p1 * 0.32 * (1 - z * z));
      y = H * 0.82 - Math.min(240, bump * 90);
      if (x === 35) ctx.moveTo(x, y); else ctx.lineTo(x, y);
    } else if (id === 'bsd') {
      const z = (u - 0.5) * 4.0;
      const lFunc = Math.pow(z, p1) * (1 + 0.25 * p2 * z * z);
      y = cy - Math.max(-120, Math.min(120, lFunc * 45));
      if (x === 35) ctx.moveTo(x, y); else ctx.lineTo(x, y);
    } else if (id === 'snell') {
      const z = (u - 0.5) * 3.0;
      const obst = p2 * Math.exp(-2.2 * z * z) * Math.cos(2.5 * z);
      const snell = Math.max(obst, p2 * Math.exp(-0.55 * p1 * Math.abs(z)));
      y = H * 0.8 - snell * 170;
      if (x === 35) ctx.moveTo(x, y); else ctx.lineTo(x, y);
    } else {
      const gap = 1 - (2 * Math.sqrt(p1)) / (p1 + 1);
      const mix = Math.pow(1 - gap, u * p2);
      y = H * 0.82 - mix * 210;
      if (x === 35) ctx.moveTo(x, y); else ctx.lineTo(x, y);
    }
  }
  ctx.stroke();

  if (id === 'kam') {
    const err = (p1 * Math.pow(0.35, Math.pow(2, p3 - 1))).toFixed(5);
    return { metric1: `|⟨k,ω⟩| ≥ γ|k|^{-${p2.toFixed(1)}}`, metric2: `Newton Error ε_${p3} = ${err}`, metric3: 'Invariant KAM Torus Locked', statusText: `Quadratic Newton smoothing step n=${p3} converged` };
  }
  if (id === 'rg') {
    const contract = Math.pow(p3, -p2 * p1).toFixed(4);
    return { metric1: `Scale Factor b^k = ${Math.pow(p3, p1)}`, metric2: `Irrelevant Coupling = ${contract}×`, metric3: 'Wilson–Fisher Fixed Point Attractor', statusText: `High-frequency shells integrated out across ${p1} steps` };
  }
  if (id === 'lll') {
    const epd = (Math.E * (p2 / 100) * (p1 + 1)).toFixed(2);
    const subcrit = Number(epd) <= 1.0;
    return { metric1: `e · p · (d+1) = ${epd}`, metric2: subcrit ? '≤ 1.0 (Subcritical Tree)' : '> 1.0 (Supercritical)', metric3: subcrit ? 'O(n) Expected Resamplings' : 'Decrease p or d for LLL guarantee', statusText: `Witness tree branching factor = ${epd}` };
  }
  if (id === 'sos') {
    return { metric1: `SoS Certificate Degree = ${p1}`, metric2: `Gram Matrix Rank = ${p3}`, metric3: `f(x) - c* = ∑ q_i(x)² ≥ 0`, statusText: `Semidefinite Positivstellensatz witness verified` };
  }
  if (id === 'carleman') {
    const gain = (Math.pow(p1, 3) * p2).toFixed(1);
    return { metric1: `Spotlight Weight τ = ${p1}`, metric2: `Commutator Gain τ³‖v‖² = ${gain}`, metric3: 'Unique Continuation Certified', statusText: `Exponential Carleman weight e^{τφ} amplifies hidden support` };
  }
  if (id === 'bsd') {
    const reg = (1.25 + p1 * 0.65 * (1 - 0.15 * p2)).toFixed(3);
    return { metric1: `ord_{s=1} L(E,s) = ${p1}`, metric2: `Néron–Tate Regulator = ${reg}`, metric3: `|Ш[p^∞]| Dim = ${p3}`, statusText: `Selmer exact sequence rank = ${p1} + ${p3}` };
  }
  if (id === 'snell') {
    const xStar = (0.42 / Math.sqrt(p1)).toFixed(2);
    return { metric1: `Free Boundary x* = ±${xStar}`, metric2: `min(-Lu, u - g) = 0`, metric3: 'C^{1,1} Smooth Pasting Active', statusText: `Snell envelope dominates obstacle payoff g(x)` };
  }
  if (id === 'decoupling') {
    const l2Sum = (p1 * 0.42).toFixed(2);
    const naiveSum = (p1 * p1 * 0.42).toFixed(1);
    return { metric1: `Naive Bound = ${naiveSum}`, metric2: `Decoupled l² = ${l2Sum}`, metric3: `Zeta Exponent σ ≤ 2/3`, statusText: `Transverse curvature κ=${p2} decouples ${p1} paraboloid caps` };
  }
  if (id === 'pfr') {
    const distAfter = (Math.log2(p1) * Math.pow(0.65, p2)).toFixed(3);
    const cosets = Math.round(Math.pow(p1, 6.2));
    return { metric1: `d_H(X_m, X_m) = ${distAfter} bits`, metric2: `Coset Cover ≤ ${cosets} shifts`, metric3: `Polynomial Freiman–Ruzsa Certified`, statusText: `Entropic Ruzsa distance contracted across ${p2} steps` };
  }
  if (id === 'glimm') {
    const qInit = (p1 * 1.8).toFixed(2);
    const qNow = Math.max(0.15, p1 * 1.8 - p3 * 0.32 * p2).toFixed(2);
    return { metric1: `Initial Q_0 = ${qInit}`, metric2: `Current Glimm H = ${qNow}`, metric3: `BV Total Variation Bounded`, statusText: `${p3} shock collisions absorbed by quadratic Glimm potential` };
  }
  if (id === 'khovanov') {
    const sInv = Math.max(0, p1 - p2 + 1);
    const g4Bound = Math.ceil(sInv / 2);
    return { metric1: `Rasmussen |s(K)| = ${sInv}`, metric2: `Smooth 4D Genus g_4(K) ≥ ${g4Bound}`, metric3: `Milnor / Torus Slice Certified`, statusText: `Lee spectral sequence page converged at genus ${g4Bound}` };
  }
  if (id === 'onsager') {
    const exp = (3 * p1 - 1).toFixed(2);
    const conserved = p1 > 0.334;
    const flux = Math.pow(2, -p2 * Math.max(-0.5, 3 * p1 - 1)).toFixed(4);
    return { metric1: `3α - 1 = ${exp}`, metric2: `Scale Flux Π_ℓ = ${flux}`, metric3: conserved ? 'Energy Conserved (α > 1/3)' : 'Anomalous Dissipation (α ≤ 1/3)', statusText: `Constantin-E-Titi commutator at scale ℓ = 2^{-${p2}}` };
  }
  if (id === 'bubbling') {
    const maxBubbles = Math.floor(p1 / p2);
    const remE = (p1 - maxBubbles * p2).toFixed(2);
    return { metric1: `Max Bubbles ≤ ${maxBubbles}`, metric2: `Quantum ħ₀ = ${p2.toFixed(1)}`, metric3: `Principal Curve E = ${remE}`, statusText: `Gromov compactness tree with ${maxBubbles} quantized S² bubbles` };
  }
  if (id === 'nilmanifold') {
    const uNorm = Math.pow(p2, Math.pow(2, p1 - 1)).toFixed(4);
    return { metric1: `‖f‖_{U^${p1-1}} ≥ ${uNorm}`, metric2: `${p3}-Step Nilmanifold G/Γ`, metric3: `${p1}-AP Recurrence Guaranteed`, statusText: `Host-Kra characteristic factor isolates ${p1}-term progressions` };
  }
  if (id === 'localization') {
    const exactSum = (p2 * (1.5 / p3)).toFixed(3);
    return { metric1: `Fixed Points |M^T| = ${p2}`, metric2: `Exact Sum = ${exactSum}`, metric3: `Stationary Phase Error = 0`, statusText: `Equivariant coboundary d_G α vanishes at t = ${p1}` };
  }
  if (id === 'bochner') {
    const totalP = (p2 + p1 * p3).toFixed(2);
    const vanishes = p1 > 0;
    return { metric1: `⟨Δω, ω⟩ = ${totalP}`, metric2: `Curvature Gain = ${(p1 * p3).toFixed(2)}`, metric3: vanishes ? 'H^p_dR(M) = 0 (Vanishes!)' : 'Curvature allows harmonic forms', statusText: `Weitzenböck decomposition Δ = ∇*∇ + ${p1}·p` };
  }
  if (id === 'barron') {
    const err = ((p2 * p2) / p1).toFixed(4);
    return { metric1: `L² Error ≤ ${err}`, metric2: `Rate = C_f² / k (1/${p1})`, metric3: `Dimension d = ${p3} Independent!`, statusText: `Maurey empirical average over k = ${p1} Fourier atoms` };
  }
  if (id === 'junta') {
    const juntaSize = Math.min(4096, Math.round(Math.pow(2, (2.2 * p1) / p2)));
    return { metric1: `Junta Variables J ≤ ${juntaSize}`, metric2: `Tail Energy ≤ ${p2.toFixed(2)}`, metric3: `Bonami-Beckner ‖T_${p3}f‖₄ Controlled`, statusText: `Fourier weight concentrated on degree ≤ ${(p1 / p2).toFixed(1)}` };
  }
  if (id === 'wasserstein') {
    const convGain = (0.5 * p1 * p3 * (1 - p3) * p2 * p2).toFixed(3);
    return { metric1: `Curvature Defect = -${convGain}`, metric2: `Log-Sobolev Constant ≥ ${p1.toFixed(2)}`, metric3: `H(μ_t) Strictly Convex`, statusText: `McCann displacement interpolation at geodesic time t = ${p3}` };
  }
  if (id === 'uhlenbeck') {
    const subcrit = p1 <= p2;
    const divA = (p1 * Math.pow(0.4, p3)).toFixed(5);
    return { metric1: `‖d*A_k‖ = ${divA}`, metric2: subcrit ? `‖A‖_{W^{1,p}} ≤ ${(1.8 * p1).toFixed(2)}` : 'Uhlenbeck Bubble Pinches Off!', metric3: subcrit ? 'Coulomb Gauge Smooth' : 'Exceeds ε₀ Threshold', statusText: `Coulomb gauge Newton step k=${p3} (${subcrit ? 'subcritical' : 'supercritical'})` };
  }
  if (id === 'guthkatz') {
    const cells = Math.pow(p1, 3);
    const incBound = Math.round(p2 * p3 * 12 / p1 + p2 * p1);
    return { metric1: `${cells} Polynomial Cells`, metric2: `Incidences I(P,L) ≤ ${incBound}`, metric3: `O(N^{3/2}) Guth–Katz Bound`, statusText: `Degree D=${p1} zero set partitions ${p2*100} points` };
  }
  if (id === 'karpsipser') {
    const subcrit = p1 < 2.718;
    const coreFrac = subcrit ? 0 : Math.round((1 - 2.718 / p1) * p3);
    return { metric1: `c = ${p1.toFixed(2)} vs e ≈ 2.72`, metric2: `2-Core Size = ${coreFrac} vertices`, metric3: subcrit ? 'Complete Leaf Unraveling' : '🔥 Giant 2-Core Phase!', statusText: `Karp-Sipser leaf peeling after ${p2} rounds` };
  }
  if (id === 'stein') {
    const wDist = (p3 / Math.sqrt(p1) / Math.max(0.3, p2)).toFixed(4);
    return { metric1: `d_W(W, N(0,1)) ≤ ${wDist}`, metric2: `Rate = O(1/√${p1})`, metric3: `Stein Operator Solution Bounded`, statusText: `Exchangeable pair coupling λ = ${(p2/p1).toFixed(3)}` };
  }
  if (id === 'sle') {
    const phase = p1 <= 4.0 ? 'Simple Non-Self-Intersecting Curve' : (p1 < 8.0 ? 'Self-Touching Percolation Hull' : 'Space-Filling Peano Curve');
    const dimH = Math.min(2.0, 1 + p1 / 8).toFixed(3);
    return { metric1: `Hausdorff Dim d_H = ${dimH}`, metric2: `κ = ${p1.toFixed(2)}`, metric3: phase, statusText: `Loewner slit evolution at capacity t = ${p2}` };
  }
  if (id === 'degiorgi') {
    const theta = Math.max(0.08, 0.35 / p1);
    const oscAfter = (p3 * Math.pow(1 - theta, p2)).toFixed(4);
    const alpha = (-Math.log2(1 - theta)).toFixed(3);
    return { metric1: `Hölder Exponent α = ${alpha}`, metric2: `osc(B_{2^{-${p2}}}) = ${oscAfter}`, metric3: `C^{0,${alpha}} Interior Smoothness`, statusText: `De Giorgi level-set oscillation contracted across ${p2} scales` };
  }
  if (id === 'parkpham') {
    const pcBound = Math.min(0.99, (p2 / 100) * Math.log2(p1) * 1.4).toFixed(3);
    return { metric1: `q = ${(p2/100).toFixed(2)}`, metric2: `Critical p_c ≤ ${pcBound}`, metric3: `O(q log ℓ) Kahn–Kalai Proven!`, statusText: `Fragmentation cover size shrunk across ${p3} steps` };
  }
  if (id === 'katoponce') {
    const commNorm = (p2 * (1 + 0.15 * p1) * Math.pow(2, -0.3 * p3)).toFixed(3);
    return { metric1: `Commutator Residual = ${commNorm}`, metric2: `BKM Integral ∫‖ω‖_∞ Finite`, metric3: `s+1 Derivative Cancelled!`, statusText: `Kato-Ponce commutator in H^{${p1}} at shell N=${p3}` };
  }
  if (id === 'expander') {
    const bound = (2 * Math.sqrt(p1)).toFixed(2);
    const deg = p1 + 1;
    return { metric1: `Degree d = ${deg}, |λ₂| ≤ ${bound}`, metric2: `Spectral Gap = ${(deg - Number(bound)).toFixed(2)}`, metric3: `Mixing l² Decay = ${Math.pow(Number(bound)/deg, p2).toFixed(4)}`, statusText: `Ramanujan Hecke bound |a_p| ≤ 2√${p1} satisfied` };
  }

  // Labs 33..160: Domain-grounded 3-trace phase-space decomposition (raw dispersive wave, Lyapunov envelope, contracted core)
  const u1 = Math.max(0.02, Math.min(1.0, (p1 - (sim.p1.min || 0)) / Math.max(1e-6, (sim.p1.max || 100) - (sim.p1.min || 0))));
  const u2 = Math.max(0.02, Math.min(1.0, (p2 - (sim.p2.min || 0)) / Math.max(1e-6, (sim.p2.max || 100) - (sim.p2.min || 0))));
  const u3 = Math.max(0.02, Math.min(1.0, (p3 - (sim.p3.min || 0)) / Math.max(1e-6, (sim.p3.max || 100) - (sim.p3.min || 0))));
  const seedPhase = (parseInt(sim.num, 10) || 33) * 0.37;
  const dampRate = 0.65 + 2.4 * u3;

  // Re-paint clean oscilloscope frame for Labs 33..160 so all 3 harmonic traces stand out clearly
  ctx.fillStyle = 'rgba(5, 11, 22, 0.86)';
  ctx.fillRect(28, 22, W - 56, H - 44);

  // Trace 1: Unfiltered multi-scale oscillation (cyan)
  ctx.strokeStyle = 'rgba(56, 189, 248, 0.42)';
  ctx.lineWidth = 1.4;
  ctx.beginPath();
  for (let x = 35; x < W - 35; x += 3) {
    const u = (x - 35) / (W - 70);
    const osc = Math.sin((4 + 8 * u1) * u * Math.PI + seedPhase) + 0.45 * Math.cos((11 + 9 * u2) * u * Math.PI);
    const y = H * 0.5 - osc * 68 * (0.45 + 0.55 * u1);
    if (x === 35) ctx.moveTo(x, y); else ctx.lineTo(x, y);
  }
  ctx.stroke();

  // Trace 2: Coercive Lyapunov barrier envelope (emerald dashed)
  ctx.save();
  ctx.setLineDash([5, 4]);
  ctx.strokeStyle = 'rgba(52, 211, 153, 0.78)';
  ctx.lineWidth = 1.6;
  ctx.beginPath();
  for (let x = 35; x < W - 35; x += 4) {
    const u = (x - 35) / (W - 70);
    const env = 104 * (0.35 + 0.65 * u1) * Math.exp(-dampRate * u * (0.5 + u2));
    const y = H * 0.5 - env;
    if (x === 35) ctx.moveTo(x, y); else ctx.lineTo(x, y);
  }
  ctx.stroke();
  ctx.restore();

  // Trace 3: Contracted structured core trajectory (luminous gold)
  ctx.save();
  ctx.shadowBlur = 12;
  ctx.shadowColor = 'rgba(251, 191, 36, 0.52)';
  ctx.strokeStyle = '#fbbf24';
  ctx.lineWidth = 2.6;
  ctx.beginPath();
  for (let x = 35; x < W - 35; x += 2) {
    const u = (x - 35) / (W - 70);
    const env = 96 * (0.35 + 0.65 * u1) * Math.exp(-dampRate * u * (0.5 + u2));
    const y = H * 0.5 - env * Math.cos((3.5 + 5 * u2) * u * Math.PI + 0.5 * seedPhase);
    if (x === 35) ctx.moveTo(x, y); else ctx.lineTo(x, y);
  }
  ctx.stroke();
  ctx.restore();

  const residualTail = (Math.exp(-dampRate * (0.5 + u2)) * (1.05 - 0.45 * u2)).toFixed(4);
  const gainFactor = (1 + 3.2 * u1 * (0.5 + u3)).toFixed(2);
  const vFileShort = (sim.verifFile || '').split('/').pop();
  return {
    metric1: `${sim.p1.label.slice(0, 22)}: ${p1}`,
    metric2: `Coercive Gain = ${gainFactor}× · Tail ≤ ${residualTail}`,
    metric3: `${sim.category || 'Structural Contraction'} Locked`,
    statusText: `Lab ${sim.num} (${vFileShort}): residual contracted to ${residualTail} at ${sim.p3.label} = ${p3}`
  };
}

