    var co = m.constantOptimizer || { baselineGain: 10, donorGain: 32, tightenedExponentText: 'O(N log N)' };
    var c = '<div style="padding:12px;border-radius:10px;background:rgba(2,6,23,0.85);border:1px solid ' + accentColor + ';">';
