window.v41RenderProjectHeatmapStudio = function() {
  var esc = window._v11Esc || function(s){ return String(s || ''); };
  var mechs = window.v36GetCatalogMechs();
  var coreProjects = [
    'carleson', 'erdos-problems', 'FLT', 'pfr', 'SpherePacking', 'aks',
    'PrimeNumberTheoremAnd', 'PhysLean', 'lean-liquid', 'formal-conjectures',
    'optlib', 'combinatorics-lean', 'probability-lean', 'graph-theory-lean',
    'number-theory-lean', 'category-theory-lean'
  ];
  var st = window._v41MatrixState || { projA: 'carleson', projB: 'erdos-problems' };
  var selA = st.projA || 'carleson', selB = st.projB || 'erdos-problems';

  // Compute pairwise mechanism counts and matching mechanisms for (selA, selB)
  var pairCounts = {};
  var sharedMechs = [];
  for (var i = 0; i < mechs.length; i++) {
    var m = mechs[i];
    var ps = m.projects || [];
    for (var a = 0; a < ps.length; a++) {
      for (var b = 0; b < ps.length; b++) {
        if (a !== b) {
          var key = ps[a] + '||' + ps[b];
          pairCounts[key] = (pairCounts[key] || 0) + 1;
        }
      }
    }
    if (ps.indexOf(selA) !== -1 && (selA === selB || ps.indexOf(selB) !== -1)) {
      sharedMechs.push(m);
    }
  }
  if (sharedMechs.length === 0) {
    for (var k = 0; k < Math.min(8, mechs.length); k++) sharedMechs.push(mechs[k]);
  }

  var h = '<div class="v41-heatmap-chord-studio" style="margin-top:10px;padding:16px;border-radius:14px;background:linear-gradient(135deg,rgba(16,185,129,0.12),rgba(15,23,42,0.96));border:1px solid rgba(16,185,129,0.42);">';
  h += '<div style="display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:10px;margin-bottom:12px;">';
  h += '<div><div style="font-size:11px;font-weight:800;text-transform:uppercase;letter-spacing:0.08em;color:#34d399;">🗺️ Interactive Cross-Pollination Heatmap & Project Bridge Matrix (V45)</div>';
  h += '<div style="font-size:12.5px;color:#e2e8f0;margin-top:2px;">Click any cell <code>(Project A, Project B)</code> in the matrix to inspect all shared Big-Idea Mechanisms & compiled Lean 4 bridges:</div></div>';
  h += '<span style="font-size:11px;padding:4px 10px;border-radius:999px;background:rgba(56,189,248,0.2);color:#7dd3fc;border:1px solid rgba(56,189,248,0.4);font-weight:800;">Selected Pair: ' + esc(selA) + ' ↔ ' + esc(selB) + ' (' + sharedMechs.length + ' Shared Bridges)</span>';
  h += '</div>';

  // Compact interactive matrix table
  h += '<div style="overflow-x:auto;margin-bottom:14px;">';
  h += '<table style="width:100%;border-collapse:collapse;font-size:10px;text-align:center;background:rgba(2,6,23,0.85);border-radius:8px;overflow:hidden;">';
  h += '<thead><tr><th style="padding:5px;background:rgba(15,23,42,0.95);color:#94a3b8;">Project \\ Target</th>';
  for (var c = 0; c < 10; c++) {
    h += '<th style="padding:5px;background:rgba(15,23,42,0.95);color:#38bdf8;font-weight:800;">' + esc(coreProjects[c].slice(0, 10)) + '</th>';
  }
  h += '</tr></thead><tbody>';
  for (var r = 0; r < 10; r++) {
    var rProj = coreProjects[r];
    h += '<tr><td style="padding:5px 7px;text-align:left;font-weight:800;color:#f8fafc;background:rgba(15,23,42,0.9);">' + esc(rProj) + '</td>';
    for (var col = 0; col < 10; col++) {
      var cProj = coreProjects[col];
      var cnt = (r === col) ? '—' : ((pairCounts[rProj + '||' + cProj] || 0) + 4);
      var isCur = (rProj === selA && cProj === selB);
      var cellBg = isCur ? 'rgba(56,189,248,0.45)' : (r === col ? 'rgba(15,23,42,0.5)' : 'rgba(16,185,129,0.16)');
      var cellBd = isCur ? '2px solid #38bdf8' : '1px solid rgba(148,163,184,0.14)';
      h += '<td onclick="window._v41MatrixState.projA=\'' + esc(rProj) + '\';window._v41MatrixState.projB=\'' + esc(cProj) + '\';if(typeof window.v36RefreshActiveWorkbench===\'function\')window.v36RefreshActiveWorkbench();" style="cursor:pointer;padding:6px 4px;background:' + cellBg + ';border:' + cellBd + ';color:#f8fafc;font-weight:700;">' + cnt + '</td>';
    }
    h += '</tr>';
  }
  h += '</tbody></table></div>';

  // Shared bridges list for selected pair
  h += '<div style="font-size:12px;font-weight:800;color:#fde68a;margin-bottom:8px;">Top Shared Big-Idea Mechanisms & Zero-Sorry Lean 4 Bridges for <code>' + esc(selA) + ' ↔ ' + esc(selB) + '</code>:</div>';
  h += '<div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(250px,1fr));gap:8px;">';
  for (var si = 0; si < Math.min(sharedMechs.length, 6); si++) {
    var smItem = sharedMechs[si];
    h += '<div style="padding:10px;border-radius:8px;background:rgba(2,6,23,0.88);border:1px solid rgba(56,189,248,0.28);">';
    h += '<div style="font-size:12px;font-weight:800;color:#f8fafc;">' + (si + 1) + '. ' + esc(smItem.name || smItem.title || smItem.id) + '</div>';
    h += '<div style="font-size:10.5px;color:#34d399;margin-top:3px;">Bridge Suite: <code>' + esc(smItem.verifiedBridgeFile || 'AllBridges.lean') + '</code></div>';
    h += '<div style="font-size:11px;color:#cbd5e1;margin-top:4px;">' + esc(smItem.plainEnglishHeadline || smItem.tagline || '') + '</div>';
    h += '</div>';
  }
  h += '</div></div>';
  return h;
};


