  window.v95GetAuthenticProjects = function() {
    var mProjs = (typeof manifest !== "undefined" && manifest && manifest.projects) ||
                 (window.__CG_PRELOADED__ && window.__CG_PRELOADED__.manifest && window.__CG_PRELOADED__.manifest.projects) || {};
    var out = [];
    if (Array.isArray(mProjs)) {
      for (var i = 0; i < mProjs.length; i++) {
        if (mProjs[i] && mProjs[i].id) {
          out.push({ id: String(mProjs[i].id), name: String(mProjs[i].name || mProjs[i].id) });
        }
      }
    } else if (mProjs && typeof mProjs === "object") {
      var keys = Object.keys(mProjs);
      var preferred = ["oai-codes", "tc-geometry", "oai-qrep", "tc-reptheory", "tc-analysis", "apsp3sum", "ns", "euler", "zeta23", "eth", "pfr", "flt"];
      keys.sort(function(a, b) {
        var ia = preferred.indexOf(a);
        var ib = preferred.indexOf(b);
        if (ia !== -1 && ib !== -1) return ia - ib;
        if (ia !== -1) return -1;
        if (ib !== -1) return 1;
        return a.localeCompare(b);
      });
      for (var k = 0; k < keys.length; k++) {
        var pk = keys[k];
        var po = mProjs[pk] || {};
        out.push({ id: pk, name: String(po.name || pk) });
      }
    }
    if (!out.length) {
      out = [
        { id: "oai-codes", name: "Binary & Spherical Coding Bounds" },
        { id: "tc-geometry", name: "Tau Ceti Symplectic & Complex Geometry" },
        { id: "oai-qrep", name: "Quantum Parallel Repetition & Embezzlement" },
        { id: "tc-reptheory", name: "Tau Ceti Representation Theory" },
        { id: "tc-analysis", name: "Tau Ceti Functional & Elliptic Analysis" },
        { id: "apsp3sum", name: "Subquadratic 3SUM & Subcubic APSP" }
      ];
    }
    return out;
  };

