  window.v95FindLiveCorpusBridge = function(pA, pB) {
    var cIsos = (typeof semanticMechanisms !== "undefined" && semanticMechanisms && semanticMechanisms.customIsomorphisms) ||
                (window.__CG_PRELOADED__ && window.__CG_PRELOADED__.semanticMechanisms && window.__CG_PRELOADED__.semanticMechanisms.customIsomorphisms) || [];
    var best = null;
    for (var i = 0; i < cIsos.length; i++) {
      var iso = cIsos[i];
      if (!iso) continue;
      var a = iso.projectA || iso.projectAId;
      var b = iso.projectB || iso.projectBId;
      var matchPair = (a === pA && b === pB) || (a === pB && b === pA);
      if (matchPair && iso.epistemicSymbol === "★") {
        best = iso;
        break;
      }
      if (matchPair && !best && iso.epistemicSymbol !== "⚠") {
        best = iso;
      }
    }
    var bts = window.CG_VERIFIED_ATLAS_BREAKTHROUGHS || [];
    var matchedBt = null;
    for (var j = 0; j < bts.length; j++) {
      var projs = (bts[j] && bts[j].projects) || [];
      if (projs.indexOf(pA) !== -1 && projs.indexOf(pB) !== -1) {
        matchedBt = bts[j];
        break;
      }
    }
    return { iso: best, breakthrough: matchedBt };
  };

