        '<span class="v110-jargon-pill" data-jargon-key="' + tk + '" onmouseover="window.v110ShowJargonTooltip(this.getAttribute(&quot;data-jargon-key&quot;), event.clientX, event.clientY)" onclick="window.v110OpenGlossaryFromTip(this.getAttribute(&quot;data-jargon-key&quot;))">$1</span>'
