// === V125 Novice-First Experience Switcher, Quick-Jump Router & Universal Drill-Down / Link Handler ===
(function() {
  if (typeof window === "undefined") return;

  window._v125ExperienceLevel = 2; // Default 2 (Explorer: Plain English + Visuals + Equations)

  // Fix window.v50QuickJump so all 4 Hero Quick-Start Cards work immediately
  window.v50QuickJump = function(target) {
    if (target === "wizard") {
      // Jump to Galaxy / Serendipity Obstacle Problem Matcher or open Bridge Composer Studio
      if (window.v95OpenBridgeComposerStudio) {
        window.v95OpenBridgeComposerStudio();
      }
    } else if (target === "trinities") {
      if (typeof state !== "undefined") {
        state.lens = "serendipity";
        state.serenSubmode = "mechanisms";
      }
      if (typeof syncUrl === "function") syncUrl(false);
      if (typeof renderApp === "function") renderApp();
      var el = document.getElementById("app-mount");
      if (el && el.scrollIntoView) el.scrollIntoView({ behavior: "smooth" });
    } else if (target === "lean4") {
      if (typeof state !== "undefined") {
        state.lens = "serendipity";
        state.serenSubmode = "verified";
      }
      if (typeof syncUrl === "function") syncUrl(false);
      if (typeof renderApp === "function") renderApp();
      var el2 = document.getElementById("app-mount");
      if (el2 && el2.scrollIntoView) el2.scrollIntoView({ behavior: "smooth" });
    }
  };

  window.v125ToggleSingleCodeBlock = function(btn) {
    if (!btn || !btn.nextElementSibling) return;
    var pre = btn.nextElementSibling;
    var isShown = pre.classList.contains("v125-force-show");
    if (isShown) {
      pre.classList.remove("v125-force-show");
      btn.innerHTML = "Drill Down: Show Technical Code &amp; Formal Proof ▾";
    } else {
      pre.classList.add("v125-force-show");
      btn.innerHTML = "▴ Hide Technical Code (Return to Plain English)";
    }
  };

  window.v125InjectDrillDownButtons = function() {
    var pres = document.querySelectorAll("pre.code-block");
    for (var i = 0; i < pres.length; i++) {
      var pre = pres[i];
      if (pre.getAttribute("data-v125-wrapped") === "1") continue;
      pre.setAttribute("data-v125-wrapped", "1");
      var btn = document.createElement("button");
      btn.type = "button";
      btn.className = "v125-drilldown-toggle";
      btn.innerHTML = "Drill Down: Show Technical Code &amp; Formal Proof ▾";
      btn.setAttribute("onclick", "window.v125ToggleSingleCodeBlock(this)");
      if (pre.parentNode) {
        pre.parentNode.insertBefore(btn, pre);
      }
    }
  };

  window.v125SetExperienceLevel = function(lvl) {
    window._v125ExperienceLevel = lvl;
    for (var i = 1; i <= 3; i++) {
      var b = document.getElementById("v125-lvl-" + i);
      if (b) {
        if (i === lvl) b.classList.add("active");
        else b.classList.remove("active");
      }
    }
    if (document.body && document.body.classList) {
      if (lvl === 1) document.body.classList.add("v125-mode-novice");
      else document.body.classList.remove("v125-mode-novice");
    }
    window.v125InjectDrillDownButtons();
    var toggles = document.querySelectorAll(".v125-drilldown-toggle");
    for (var t = 0; t < toggles.length; t++) {
      toggles[t].style.display = (lvl === 1) ? "inline-flex" : "none";
    }
    var disclosures = document.querySelectorAll("details.cg-code-disclosure");
    for (var d = 0; d < disclosures.length; d++) {
      if (lvl === 3) disclosures[d].setAttribute("open", "");
      else if (lvl === 1) disclosures[d].removeAttribute("open");
    }
  };

  // Ensure all external links open safely in a new tab with clear tooltips
  window.v125EnhanceLinks = function() {
    var links = document.querySelectorAll("#app-mount a[href]");
    for (var i = 0; i < links.length; i++) {
      var a = links[i];
      var href = a.getAttribute("href") || "";
      if (href.indexOf("http://") === 0 || href.indexOf("https://") === 0) {
        a.setAttribute("target", "_blank");
        a.setAttribute("rel", "noopener noreferrer");
        if (!a.getAttribute("title")) {
          a.setAttribute("title", "Opens external source repository in a new tab (" + href + ")");
        }
      }
    }
  };
})();


// === V131 / V199 Imported v34 Epistemic Catalogue Explorer Modal (24 Concept Questions · 26 Graded Connections · 593 Projects + Epistemic Triad SVG) ===
