      '  <rect x="16" y="30" width="146" height="50" rx="8" fill="rgba(16,185,129,0.13)" stroke="#10b981" stroke-width="1.2"/>',
      '  <text x="26" y="48" fill="#6ee7b7" font-size="10.5" font-weight="800">1. Shared Mechanism</text>',
      '  <text x="26" y="65" fill="#cbd5e1" font-size="9.5">Invariant / operator skeleton</text>',
      '  <path class="cg-svg-photon-arc" d="M 162 49 Q 175 36 188 49" fill="none" stroke="#34d399" stroke-width="1.8"/>',
      '  <path d="M 162 61 Q 175 74 188 61" fill="none" stroke="rgba(245,158,11,0.55)" stroke-width="1.3" stroke-dasharray="3,2"/>',
      '  <rect x="188" y="30" width="152" height="50" rx="8" fill="rgba(245,158,11,0.13)" stroke="#f59e0b" stroke-width="1.2"/>',
      '  <text x="198" y="48" fill="#fcd34d" font-size="10.5" font-weight="800">2. What Changes</text>',
