      rowsSvg,
      '  <line x1="536" y1="14" x2="536" y2="178" stroke="rgba(148,163,184,0.24)" stroke-width="1"/>',
      '  <text x="554" y="22" fill="#fde68a" font-size="10" font-weight="800" letter-spacing="0.05em">CLOUDFLARE R2 UNLIMITED .LEAN STREAMING LANE</text>',
      '  <rect x="554" y="34" width="308" height="62" rx="8" fill="rgba(16,185,129,0.11)" stroke="#10b981" stroke-width="1.2"/>',
      '  <text x="566" y="54" fill="#6ee7b7" font-size="11" font-weight="800">R2 Bucket: common-ground-lean-corpus</text>',
      '  <text x="566" y="72" fill="#e2e8f0" font-size="10">Bound as LEAN_CORPUS_BUCKET · Zero 25 MiB cap on .lean files</text>',
      '  <text x="566" y="87" fill="#94a3b8" font-size="9.5">Pages Function /api/lean/[[path]].js streams full proofs on demand</text>',
