  // -------------------------------------------------------------------------
  // C. 2-ROLE SINGLE-PROJECT NOTE MATCHER (source-note-matcher.mjs) + LIVE UI INJECTION
  // -------------------------------------------------------------------------
  var NOTE_INFLECTIONS = {
    counts:"count", coefficients:"coefficient", laws:"law", distributions:"distribution",
    measures:"measure", moments:"moment", matrices:"matrix", kernels:"kernel", groups:"group",
    maps:"map", weights:"weight", components:"component", blocks:"block", observations:"observation",
    decoders:"decoder", exceptions:"exception", errors:"error", probabilities:"probability",
    functions:"function", derivatives:"derivative", totals:"total", braids:"braid", crossings:"crossing",
    traces:"trace", invariants:"invariant", moves:"move", subgroups:"subgroup", surjections:"surjection",
    inverses:"inverse", scales:"scale", cutoffs:"cutoff", budgets:"budget", estimates:"estimate",
    polynomials:"polynomial", quotients:"quotient", measurements:"measurement", inputs:"input",
    squares:"square", norms:"norm", projections:"projection", decisions:"decision", scores:"score",
    channels:"channel", priors:"prior", losses:"loss", quantiles:"quantile", atoms:"atom",
    spaces:"space", topologies:"topology", unions:"union", coordinates:"coordinate",
    determinants:"determinant", sums:"sum", defects:"defect", symmetries:"symmetry", orbits:"orbit"
  };

  window.v148RankSourceNotes = function(queryStr) {
    var cat = window.THEOREM_ATLAS_V36 || window.V34_CATALOGUE || {};
    var notes = cat.mechanismNotes || [];
    var rawWords = String(queryStr || "").toLowerCase().match(/[a-z0-9]+/g) || [];
    var qSet = new Set(rawWords.map(function(w){ return NOTE_INFLECTIONS[w] || w; }).filter(function(w){ return w.length > 2; }));
    if (qSet.size < 2) return [];
    var out = [];
    notes.forEach(function(note) {
      var sig = note.signature;
      if (!sig || !Array.isArray(sig.roles)) return;
      var matchedRoles = [];
      sig.roles.forEach(function(role) {
        var hits = [];
        (role.phrases || []).forEach(function(ph) {
          var pTokens = String(ph).toLowerCase().match(/[a-z0-9]+/g) || [];
          pTokens.forEach(function(pt) {
            var norm = NOTE_INFLECTIONS[pt] || pt;
            if (qSet.has(norm) && hits.indexOf(norm) === -1) hits.push(norm);
          });
        });
        if (hits.length > 0) matchedRoles.push({ name: role.name, hits: hits });
      });
      if (matchedRoles.length >= 2) {
        var totalHits = matchedRoles.reduce(function(acc, r){ return acc + r.hits.length; }, 0);
        out.push({
          id: note.id,
          kind: "note",
          title: note.title,
          projectId: note.projectId,
          grade: note.evidenceGrade,
          score: matchedRoles.length * 25 + totalHits * 8,
          matchedRoles: matchedRoles,
          requiredAssumptions: sig.requiredAssumptions || [],
          obstructions: sig.obstructions || []
        });
      }
    });
    out.sort(function(a, b){ return b.score - a.score; });
    return out;
  };

  var origV137UpdateMatcherUI = window.v137UpdateMatcherUI;
  if (typeof origV137UpdateMatcherUI === "function") {
    window.v137UpdateMatcherUI = function(qVal) {
      origV137UpdateMatcherUI(qVal);
      var mount = document.getElementById("v137-matcher-mount");
      if (!mount) return;
      var noteHits = window.v148RankSourceNotes(qVal);
      var noteHtml = noteHits.length > 0
        ? '<div style="margin-top:10px;padding-top:10px;border-top:1px solid rgba(52,211,153,0.35);">' +
          '<div style="font-size:11px;font-weight:800;color:#6ee7b7;margin-bottom:6px;">◆ MATCHING SINGLE-PROJECT MECHANISM NOTES (2-ROLE ANCHOR RULE · ' + noteHits.length + ' MATCHED)</div>' +
          noteHits.slice(0, 4).map(function(nh) {
            var rolePills = nh.matchedRoles.map(function(mr) {
              return '<span style="font-size:10px;font-weight:700;background:rgba(16,185,129,0.18);border:1px solid rgba(16,185,129,0.45);color:#6ee7b7;padding:2px 8px;border-radius:999px;">✓ ' + escHtml(mr.name) + ' (' + escHtml(mr.hits.join(", ")) + ')</span>';
            }).join(" ");
            return '<div style="background:rgba(6,20,28,0.92);border:1px solid rgba(52,211,153,0.35);border-radius:10px;padding:10px 12px;margin-bottom:6px;">' +
              '<div style="display:flex;justify-content:space-between;align-items:center;gap:8px;flex-wrap:wrap;margin-bottom:4px;">' +
                '<strong style="font-size:13px;color:#fff;">◆ ' + escHtml(nh.title) + '</strong>' +
                '<div style="display:flex;gap:6px;align-items:center;">' +
                  '<span style="font-size:11px;color:#fcd34d;font-weight:700;">' + escHtml(nh.projectId) + ' · ' + nh.score + ' pts</span>' +
                  '<button type="button" class="v60-qs-btn" style="font-size:10.5px;padding:2px 7px;border-color:#38bdf8;color:#bae6fd;" onclick="window.v137CloseMatcherModal();window.v148OpenArgumentAndWorksheetModal(\'compare\',\'note:' + escHtml(nh.id) + '\');">Compare</button>' +
                '</div>' +
              '</div>' +
              '<div style="display:flex;flex-wrap:wrap;gap:5px;">' + rolePills + '</div>' +
            '</div>';
          }).join("") +
          '</div>'
        : '<div style="margin-top:8px;font-size:11px;color:#94a3b8;">◆ <em>Single-project mechanism notes require matching ≥ 2 distinct mathematical roles (try e.g. <code>braid crossing markov trace invariant</code> or <code>channel prior decision loss</code>).</em></div>';
      mount.innerHTML = mount.innerHTML + noteHtml;
    };
  }

