    var radius = 0.14 + 0.72 * Math.sqrt((seed % 10000) / 10000);
    var angle = (fIdx * Math.PI * 2) / Math.max(1, famIds.length) + radius * 2.85 + (((seed >>> 14) % 1000) / 1000 - 0.5) * 0.92;
