  function escSvgText185(s, maxLen) {
    var raw = String(s || "").replace(/\s+/g, " ").trim();
    if (maxLen && raw.length > maxLen) raw = raw.slice(0, maxLen - 1) + "…";
    return raw
      .replace(/&/g, "&amp;")
      .replace(/</g, "&lt;")
      .replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;");
  }

