        cflViscosityTerm: cflViscosityTerm, upwindRatioPct: upwindRatioPct, crankNicolsonRatioPct: crankNicolsonRatioPct,
        q3: q, p3: p, q3Sq: q * q, shadowH0: shadowH0, shadowH3: shadowH3, shadowDiscCoeff: shadowDiscCoeff,
